  /// Which of the desktop's own Upcoming/Past tabs is showing. Separate from
  /// the mobile Scaffold's DefaultTabController — the desktop branch renders
  /// its own tab row rather than sharing that TabBar's widgets, so it needs
  /// its own index.
  int _desktopTabIndex = 0;

  /// The booking selected in the desktop left-hand list. Left null rather
  /// than defaulted eagerly in initState — the booking stream has not loaded
  /// anything yet at that point — so _buildDesktop falls back to "first
  /// booking in the current list" itself on every build until the guest
  /// actually clicks a card.
  String? _selectedBookingId;

  /// Loads any listing referenced by a booking that has not been fetched.
  ///
  /// Guarded by _requested so a rebuilding stream does not re-query the same
  /// ids forever — the StreamBuilder can rebuild many times per second while
  /// Firestore settles.
  void _ensureListings(List<StayBooking> bookings) {
    final List<String> missing = bookings
        .map((b) => b.listingId)
        .where((id) => id.isNotEmpty && !_requested.contains(id))
        .toSet()
        .toList();
    if (missing.isEmpty) return;

    _requested.addAll(missing);
    _fetchListings(missing);
  }

  /// try/catch, not .catchError.
  ///
  /// This was `.then(...).catchError((_) => <StayListing>[])`, which the
  /// analyzer rejects: the `then` returns `Future<void>`, so the error handler
  /// must return void or null — a list is not assignable to it. Awaiting in a
  /// plain async method sidesteps the whole question and reads better.
  Future<void> _fetchListings(List<String> ids) async {
    try {
      final List<StayListing> found =
          await StayListingService.instance.byIds(ids);
      if (!mounted) return;
      setState(() {
        for (final l in found) {
          _listings[l.id] = l;
        }
      });
    } catch (_) {
      // Swallowed on purpose. The dates, status and reference all come from
      // the booking itself; a missing title is a worse card, not a broken one.
    }
  }

