  // ── Status ───────────────────────────────────────────────────────────────
  //
  // Every status the enum can hold gets a label and a colour. A switch with no
  // default means adding a status to BookingStatus breaks the build here
  // rather than rendering a blank chip.
  ({String label, Color colour}) _statusChip(BookingStatus s) {
    switch (s) {
      case BookingStatus.pending:
        return (label: 'AWAITING HOST', colour: GoOutsColors.pendingOrange);
      case BookingStatus.confirmed:
        return (label: 'CONFIRMED', colour: GoOutsColors.successGreen);
      case BookingStatus.inProgress:
        return (label: 'YOU ARE THERE', colour: GoOutsColors.primaryBlue);
      case BookingStatus.completed:
        return (label: 'COMPLETED', colour: GoOutsColors.bodyText);
      case BookingStatus.declined:
        return (label: 'DECLINED', colour: GoOutsColors.error);
      case BookingStatus.cancelledGuest:
        return (label: 'YOU CANCELLED', colour: GoOutsColors.error);
      case BookingStatus.cancelledHost:
        return (label: 'HOST CANCELLED', colour: GoOutsColors.error);
      case BookingStatus.disputed:
        return (label: 'UNDER REVIEW', colour: GoOutsColors.warning);
    }
  }

  static const List<String> _months = <String>[
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December',
  ];

  /// "12 to 14 July" when one month, "30 July to 2 August" when it spans two.
  static String _dateRange(DateTime a, DateTime b) => a.month == b.month
      ? '${a.day} to ${b.day} ${_months[b.month - 1]}'
      : '${a.day} ${_months[a.month - 1]} to ${b.day} ${_months[b.month - 1]}';

  /// null when the stay is not ahead of us.
  static String? _countdown(DateTime checkIn) {
    final DateTime today = DateTime.now();
    final int days = DateTime(checkIn.year, checkIn.month, checkIn.day)
        .difference(DateTime(today.year, today.month, today.day))
        .inDays;
    if (days < 0) return null;
    if (days == 0) return 'Today';
    if (days == 1) return 'Tomorrow';
    return 'In $days days';
  }

