                      Expanded(
                        child: Text(
                          // Falls back to the reference while the listing
                          // loads, so the card is never nameless.
                          // ⚠ THE SHORT CODE, NOT THE RAW ID. Screen 13 shows
                          // GOS-XXXXX-X, so a fallback printing the twenty
                          // character Firestore id here would give a guest two
                          // different strings for the same booking.
                          listing?.title ??
                              'Booking ${stayBookingReference(b.id)}',
                          overflow: TextOverflow.ellipsis,
                          style: GoogleFonts.inter(
                            fontSize: 14,
                            fontWeight: FontWeight.w600,
                            color: GoOutsColors.deepNavy,
                          ),
                        ),
                      ),
                      if (countdown != null) ...[
                        const SizedBox(width: 8),
                        Text(
                          countdown,
                          style: GoogleFonts.inter(
                            fontSize: 14,
                            fontWeight: FontWeight.w500,
                            color: GoOutsColors.primaryBlue,
                          ),
                        ),
                      ],
                    ],
                  ),
                  const SizedBox(height: 4),
                  Text(
                    '${_dateRange(b.checkIn, b.checkOut)} · '
                    '${b.nights} ${b.nights == 1 ? 'night' : 'nights'}',
                    style: GoogleFonts.inter(
                        fontSize: 15, color: GoOutsColors.bodyText),
                  ),
                  if ((listing?.address.town ?? '').isNotEmpty)
                    Text(
                      listing!.address.town,
                      style: GoogleFonts.inter(
                          fontSize: 15, color: GoOutsColors.bodyText),
                    ),
                  const SizedBox(height: 16),
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 12, vertical: 6),
                        decoration: BoxDecoration(
                          color: chip.colour.withValues(alpha: 0.1),
                          borderRadius: BorderRadius.circular(8),
                        ),
                        child: Text(
                          chip.label,
                          style: GoogleFonts.inter(
                            fontSize: 12,
                            fontWeight: FontWeight.w700,
                            color: chip.colour,
                            letterSpacing: 0.5,
                          ),
                        ),
                      ),
                      Text(
                        'View details',
                        style: GoogleFonts.inter(
                          fontSize: 14,
                          fontWeight: FontWeight.w600,
                          color: GoOutsColors.primaryBlue,
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}
